-- Dansk portion 7 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6596-9985.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish7'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish7', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6596,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'To hjemmesider skriver om, hvor meget søvn unge har brug for. Den ene er fra et sygehus og er skrevet af en læge med henvisninger til undersøgelser, men den er ti år gammel. Den anden er fra i år og har 5.000 likes, men den er skrevet af en bruger, der kalder sig Søvnkongen og sælger puder på samme side. Mikkel vælger den nye side, fordi den er opdateret.' Hvad overser Mikkel?","o":["At den gamle side er for gammel til, at nogen kan bruge den","At søvn er noget, man slet ikke kan undersøge med sikkerhed","At Søvnkongen vil sælge puder til dem, der læser siden","At mange likes er et sikkert tegn på, at en tekst er sand"],"a":"At Søvnkongen vil sælge puder til dem, der læser siden","r":"Nyt er ikke det samme som rigtigt. Søvnkongen er anonym og sælger puder, så man skal også tænke på, hvem der skriver, og hvorfor, ikke kun på datoen."},
{"l":6617,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Vi skal til ___ i musikhuset i aften.'","o":["konsert","koncerrt","kongcert","koncert"],"a":"koncert","r":"Lyden s skrives her med c, som i mange ord fra latin og fransk."},
{"l":6634,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket landskab er Steen Steensen Blicher især kendt for at skildre?","o":["Den jyske hede","Bornholms klipper","De lollandske roemarker","Københavns baggårde"],"a":"Den jyske hede","r":"Blicher var præst og forfatter i Jylland. Hans noveller foregår ofte på den jyske hede."},
{"l":6656,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find stavemåden: 'Hun klædte sig ud i et flot ___ til fastelavn.'","o":["kustume","kostume","kostyme","kostumme"],"a":"kostume","r":"Ordet stammer fra fransk og skrives med o, u og ét m."},
{"l":6678,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Partierne indgår et 'forlig'. Hvad er det?","o":["et skænderi, der varer i mange år","en afstemning blandt alle vælgerne","en aftale, der løser en uenighed","en liste over partiernes kandidater"],"a":"en aftale, der løser en uenighed","r":"Forlig kommer af at blive forligt, altså enige. I politik er det en aftale mellem flere partier om en bestemt sag."},
{"l":6700,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning skriver forkortelsen af 'cirka' rigtigt?","o":["Turen tager c.a. to timer.","Turen tager ca, to timer.","Turen tager c. a. to timer.","Turen tager ca. to timer."],"a":"Turen tager ca. to timer.","r":"'Cirka' er ét ord, så forkortelsen har ét punktum til sidst."},
{"l":6716,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Lægen siger, hvordan sygdommen forventes at udvikle sig. Hvad kaldes sådan en vurdering?","o":["en prognose","en diagnose","en recept","en injektion"],"a":"en prognose","r":"'Pro' betyder før, så en prognose er en forudsigelse. Diagnosen fortæller derimod, hvilken sygdom man har."},
{"l":6736,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Bang! Døren smækkede, og vasen klirrede mod gulvet.' Hvilket virkemiddel er 'bang'?","o":["ironi","lydord","sammenligning","symbol"],"a":"lydord","r":"Et lydord efterligner en lyd. Det gør, at læseren næsten kan høre det, der sker."},
{"l":6760,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad mangler? 'Læreren skrev en kort ___ under min stil.'","o":["komentar","kommenntar","kommentar","kommentaar"],"a":"kommentar","r":"Ordet har dobbelt-m og ét n og slutter på -ar."},
{"l":6776,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'delegation', der rejser til et møde i udlandet?","o":["en lang liste over alle mødets deltagere","en særlig tilladelse til at rejse ind i landet","en gave, som man giver til mødets vært","en lille gruppe, der repræsenterer andre"],"a":"en lille gruppe, der repræsenterer andre","r":"En delegation er en gruppe, der er udpeget til at repræsentere f.eks. et land eller en organisation."},
{"l":6798,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en person, der 'redigerer' en film?","o":["klipper optagelserne sammen","skriver musikken til filmen","spiller hovedrollen i filmen","sælger billetterne til filmen"],"a":"klipper optagelserne sammen","r":"At redigere er at bearbejde et materiale, så det bliver færdigt. Det gælder både film og tekst."},
{"l":6807,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvordan skrives talesprogets 'ku' i formelt skriftsprog: 'Jeg ku ikke komme i går.'?","o":["kan","kunne","kunnet","kendte"],"a":"kunne","r":"'Ku' er en kort talesprogsform af datidsformen 'kunne'. I formel tekst skriver man den fulde form."},
{"l":6828,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'koge suppe på et søm'?","o":["at blande sig i andres sager","at gentage sig selv mange gange","at få meget ud af næsten ingenting","at love mere, end man kan holde"],"a":"at få meget ud af næsten ingenting","r":"Udtrykket stammer fra et gammelt folkeeventyr om en vandringsmand, der påstår, at han kan koge suppe på et søm alene."},
{"l":6851,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er en høflig omskrivning af bydeformen 'Luk vinduet'?","o":["Du lukkede vinduet.","Vinduet er lukket nu.","Vinduet lukkes aldrig.","Vil du lukke vinduet?"],"a":"Vil du lukke vinduet?","r":"Et spørgsmål med 'vil du' opfordrer på en blødere måde end bydeformen. De andre sætninger fortæller kun noget."},
{"l":6871,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Farfar smagte på suppen og sagde ingenting. Han rakte ud efter saltet og så efter peberet. Til sidst hentede han også chilien. Min søster og jeg så på hinanden, for det var os, der havde lavet den.' Hvad forstår børnene, da farfar henter chilien?","o":["At suppen ikke smager af ret meget.","At farfar synes, at suppen er blevet alt for stærk.","At farfar er så glad for suppen, at han vil have mere.","At farfar har glemt at komme krydderier i sin suppe."],"a":"At suppen ikke smager af ret meget.","r":"Farfar bliver ved med at komme mere i suppen: salt, peber og chili. Det gør man ikke, hvis den smager af nok, så børnene kan se, at den smager af for lidt."},
{"l":6893,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er hjælpeverbum (modalverbum) i: 'Mathilde kan spille på klaver.'?","o":["spille","kan","på","klaver"],"a":"kan","r":"'Kan' er et modalverbum, som står sammen med navneformen 'spille' og siger noget om evne eller mulighed."},
{"l":6906,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et land ønsker at bevare sin 'suverænitet'. Hvad er det?","o":["sin pligt til at betale bidrag til nabolandene","sin evne til at vinde store sportsstævner","sin ret til selv at bestemme over sit land","sit krav om at have et kongehus"],"a":"sin ret til selv at bestemme over sit land","r":"Et suverænt land styrer selv sine indre og ydre forhold og er ikke underlagt en anden stat."},
{"l":6928,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket tal går oftest igen i folkeeventyr, f.eks. i brødre, ønsker og prøver?","o":["fem","otte","elleve","tre"],"a":"tre","r":"Tretallet er en fast regel i folkeeventyr. Tre brødre, tre prøver og tre ønsker giver struktur og spænding."},
{"l":6951,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Forskeren gav et specifikt eksempel.' Hvad betyder 'specifikt' her?","o":["bestemt og præcist","gammelt og velkendt","sjovt og underholdende","løst og almindeligt"],"a":"bestemt og præcist","r":"Specifik betyder særlig for det enkelte tilfælde. Det modsatte er generel eller almen."},
{"l":6970,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sommerens lyd er ikke fuglene. Det er den fjerne plæneklipper, der minder en om, at nogen et sted arbejder, mens man selv ligger ned med en bog.' Hvilken tone har teksten?","o":["Truende mørk","Dovent tilfreds","Bittert vred","Dybt sørgmodig"],"a":"Dovent tilfreds","r":"Skribenten nyder at ligge ned, mens andre arbejder. Tonen er rolig og lidt drilsk, ikke vred eller trist."},
{"l":6992,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Et fyrtårn lyser ikke bare. Hvert fyr har sit eget blinkmønster, som kan slås op i søkort. To fyr på samme kyst blinker aldrig på samme måde.' Hvad kan en sømand bruge blinkmønsteret til?","o":["At se, hvor dybt vandet er","At vide, hvad klokken er","At finde ud af, hvor han er","At forudsige vejret"],"a":"At finde ud af, hvor han er","r":"Mønsteret er unikt og står i søkortet. Sømanden kan dermed se, hvilket fyr han ser, og derfor hvor han befinder sig."},
{"l":7008,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Vores nye støvsuger bruger 30 procent mindre strøm end den gamle model.' Hvilken appelform er der her?","o":["etos","patos","ironi","logos"],"a":"logos","r":"Reklamen bruger et tal og en saglig sammenligning. Det appellerer til fornuften, altså logos."},
{"l":7026,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I kemi kan man tilsætte en 'katalysator'. Hvad gør den?","o":["øger reaktionens fart uden selv at blive brugt op","standser enhver reaktion, så snart den tilsættes","farver væsken, så man kan følge reaktionen","afkøler stofferne, så de ikke bliver for varme"],"a":"øger reaktionens fart uden selv at blive brugt op","r":"En katalysator får en kemisk reaktion til at forløbe lettere og er uændret bagefter. Enzymer er katalysatorer i kroppen."},
{"l":7056,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En syre og en base 'neutraliserer' hinanden. Hvad sker der?","o":["de eksploderer ved kontakt","de ophæver hinandens virkning","de bliver begge stærkere","de skilles i to lag"],"a":"de ophæver hinandens virkning","r":"Når syre og base blandes i de rigtige mængder, bliver væsken hverken sur eller basisk, men neutral."},
{"l":7072,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er hjemlen i et argument?","o":["Den afsender, der har skrevet hele argumentet ned","Det eksempel, som gør argumentet sjovt at læse","Den antagelse, der forbinder belægget med påstanden","Den overskrift, der står over hele debatindlægget"],"a":"Den antagelse, der forbinder belægget med påstanden","r":"Hjemlen er den tanke, der får belægget til at støtte påstanden. Den står ofte ikke i teksten."},
{"l":7093,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren gav eleverne en 'ariadnetråd' i den svære opgave. Hvad fik de?","o":["en hård straf for at gøre det forkert","en ekstra og sværere opgave at løse","et hemmeligt svar fra en anden elev","noget, der viste vej ud af problemet"],"a":"noget, der viste vej ud af problemet","r":"I den græske myte giver Ariadne helten Theseus en tråd, så han kan finde ud af labyrinten igen."},
{"l":7113,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Klassen stemte om rejsemålet: 12 stemte på Paris, 8 på Rom og 7 på Berlin. Læreren sagde: Flertallet vil til Paris.' Hvad er upræcist ved lærerens udsagn?","o":["Paris fik flest stemmer, men ikke over halvdelen","Der er flere elever, der vil til Rom, end til Paris","Tallene viser, at Berlin vandt afstemningen","Læreren har talt forkert i de 27 stemmer"],"a":"Paris fik flest stemmer, men ikke over halvdelen","r":"12 ud af 27 er færre end halvdelen. Paris har de fleste stemmer, men 15 elever foretrak et andet sted."},
{"l":7138,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Med tom pung foran isboden led Hiba 'tantaluskvaler'. Hvad vil det sige?","o":["hun havde ondt i maven af for meget is","det pinte hende at se noget, hun ikke kunne få","hun var bange for at blive opdaget af ekspedienten","hun var meget stolt over at kunne sige nej"],"a":"det pinte hende at se noget, hun ikke kunne få","r":"I den græske myte står Tantalos i vand under frugttræer, men både vandet og frugterne viger, hver gang han rækker ud efter dem."},
{"l":7160,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Du har fem opgaver og for lidt tid. Hvad gør du, hvis du 'prioriterer' dem?","o":["du deler dem ud til andre","du skriver dem ned i en bog","du bestemmer, hvad der er vigtigst","du udskyder dem til næste uge"],"a":"du bestemmer, hvad der er vigtigst","r":"At prioritere er at sætte tingene i rækkefølge efter, hvor vigtige de er. Ordet hænger sammen med latin 'prior', som betyder 'den første'."},
{"l":7182,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord er nærmest det modsatte af 'relevant'?","o":["uforståelig","uærlig","ubemærket","uvedkommende"],"a":"uvedkommende","r":"Det, der er relevant, har betydning for sagen. Det, der er uvedkommende, har ikke noget med sagen at gøre."},
{"l":7201,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'ham' i: 'Vi så ham ved hallen i morges.'?","o":["direkte objekt","indirekte objekt","subjekt","prædikativ"],"a":"direkte objekt","r":"Spørg: Hvem så vi? Svaret er genstandsleddet, som på latin hedder direkte objekt."},
{"l":7220,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder 'som får meget gjort med en lille indsats'?","o":["effektfuld","effektiv","defekt","affekteret"],"a":"effektiv","r":"Effektiv handler om, at noget virker godt og sparer tid eller kræfter. Effektfuld handler i stedet om, at noget gør stort indtryk."},
{"l":7239,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad mangler? 'Dette lille ___ måler pulsen, mens du løber.'","o":["aparat","apparrat","apparat","apperat"],"a":"apparat","r":"Ordet har dobbelt-p, men kun ét r."},
{"l":7260,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Hvem der vinder er ikke til at sige.'?","o":["der","er","sige","vinder"],"a":"vinder","r":"'Hvem der vinder' er en ledsætning, som er grundled i sætningen. Den afsluttes med komma."},
{"l":7282,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord har fået stort med urette: 'Mange Københavnere tager færgen til Oslo fra Nordhavn.'?","o":["Københavnere","Oslo","Nordhavn","Mange"],"a":"Københavnere","r":"Selvom København er et navn, skrives indbyggerbetegnelsen københavner med lille."},
{"l":7300,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hun rettede aldrig nogen, der sagde, at hun var stille. Det var lettere end at forklare, at der i hendes hoved var så meget støj, at hun ikke kunne finde en sætning.' Hvad er uddragets pointe?","o":["Hun er blevet vant til at sidde stille i klassen uden at tale","Hun er ikke stille indeni, selv om andre tror det","Hun har svært ved at høre, hvad andre siger til hende","Hun er meget glad for, at alle omtaler hende som stille"],"a":"Hun er ikke stille indeni, selv om andre tror det","r":"Andre ser en stille pige, men inde i hovedet er der så meget støj, at hun ikke kan finde en sætning."},
{"l":7323,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken stavemåde er korrekt? 'Spejderne gik på tur i en ___ på seks.'","o":["pattrulje","patrullje","patrulje","patrule"],"a":"patrulje","r":"Ordet kommer fra fransk og har ét t og ét l efterfulgt af j."},
{"l":7342,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: '– Hvor skal du hen? spurgte Lea. – Ned til stranden, sagde Jon og tog jakken. Hun rejste sig. – Vent, jeg tager kikkerten med.' Hvilken fremstillingsform er det?","o":["referat","naturbeskrivelse","indre monolog","scenisk fremstilling"],"a":"scenisk fremstilling","r":"Vi følger personerne her og nu gennem replikker og små handlinger, næsten som på en scene."},
{"l":7365,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt her? 'Biblioteket er en ___ bygning, hvor alle må komme.'","o":["offentlig","offenlig","ofentlig","offentli"],"a":"offentlig","r":"Ordet har dobbelt-f og et t foran -lig, selvom t'et kan lyde som d."},
{"l":7385,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'kompliment'?","o":["en del, der gør noget helt færdigt","en venlig og rosende bemærkning","en høflig afvisning af en invitation","en lille gave til værten ved en fest"],"a":"en venlig og rosende bemærkning","r":"Man giver en kompliment, når man siger noget pænt til en anden. Et komplement, stavet med e, er noget andet: en del, der fuldstændiggør noget."},
{"l":7400,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hotellets brochure lover værelser af intim størrelse. Møblerne har autentisk, historisk charme. Fra altanen er der mulighed for glimt af havet.' Hvad gør sprogbrugen i brochuren?","o":["Den fortæller ærligt, at værelserne er små og slidte","Den gør hotellet mere gammeldags, end det i virkeligheden er","Den får små værelser og slidte møbler til at lyde godt","Den viser, at udsigten til havet er hotellets bedste side"],"a":"Den får små værelser og slidte møbler til at lyde godt","r":"'Intim' betyder her lille, og 'mulighed for glimt' betyder, at man næsten ikke kan se havet. Brochuren siger det ikke lige ud."},
{"l":7420,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi sælger ikke sko. Vi sælger følelsen af at være på vej.' Hvad gør reklamen?","o":["Den siger, at firmaet slet ikke har sko på lager","Den fortæller, hvad der gør skoene gode at gå i","Den advarer mod at købe sko, man ikke har brug for","Den sælger en følelse i stedet for at tale om skoene"],"a":"Den sælger en følelse i stedet for at tale om skoene","r":"Der står intet om pris eller kvalitet. Reklamen vil have dig til at tænke, at du får følelsen af at være på vej, når du køber skoene."},
{"l":7438,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder forleddet 'hydro' i 'hydrologi' og 'hydrofob'?","o":["vand","varme","luft","kraft"],"a":"vand","r":"'Hydro' kommer af græsk 'hydor', som betyder vand. Hydrologi er læren om vandets kredsløb, og noget hydrofobt afviser vand."},
{"l":7460,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Kommissæren studerede fodsporene i sneen. Kun ét sæt, og de førte ind, ikke ud.' Hvilken genre stammer teksten mest sandsynligt fra?","o":["fabel","krimi","kronik","sonet"],"a":"krimi","r":"En efterforsker og et spor, der skal tydes, er typiske elementer i en krimi. Læseren skal gætte med."},
{"l":7480,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad betyder forkortelsen 'dvs.' i en tekst?","o":["derved videre sagt","den vigtige sag","det vil sige","det var sådan"],"a":"det vil sige","r":"'Dvs.' står for 'det vil sige' og bruges, når man vil forklare noget nærmere."},
{"l":7500,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det, der rammer, er sjældent tallet. 10.000 berørte er statistik; én navngiven pige ved et hegn er en historie.' Hvad siger teksten om, hvad der bevæger læsere?","o":["At tal altid er mere pålidelige end historier","At aviser har for mange tal i deres artikler","At statistik kun bruges af dem, der vil skjule noget","At én persons historie rører os mere end store tal"],"a":"At én persons historie rører os mere end store tal","r":"Teksten beskriver virkningen, ikke hvad der er sandest. Det er forskellen på logos og patos."},
{"l":7516,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en folkevise?","o":["En gammel fortællende sang med omkvæd","En moderne popsang på dansk","En tale holdt ved en national fest","En kort fortælling om en klog ræv"],"a":"En gammel fortællende sang med omkvæd","r":"Folkeviser kendes fra middelalderen og blev overleveret ved at blive sunget. De fortæller en historie og har ofte omkvæd."},
{"l":7534,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hej alle. Vi minder om, at køleskabet i lærerværelset ikke er et museum. Mad, der har fået sit eget liv, fjernes på fredag.' Hvordan lyder beskeden?","o":["Vred, og de truer med at smide folk ud","Sjov, men de mener det alvorligt","Trist, for maden i køleskabet er blevet dårlig","Sjov, og de mener det slet ikke alvorligt"],"a":"Sjov, men de mener det alvorligt","r":"'Museum' og 'mad med sit eget liv' er sjove ord. Men maden bliver faktisk smidt ud på fredag, så det er alvor."},
{"l":7556,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En undersøgelse viser, at elever, der spiller et instrument, får højere karakterer. Derfor bør alle elever tvinges til at spille violin.' Hvilken mulig forklaring svækker slutningen mest?","o":["Violin er et sværere instrument end for eksempel klaver","Der findes elever, som allerede spiller et instrument","Forældre, der hjælper med musik, hjælper måske også med lektier","Musikundervisning koster penge, som skolen skal finde"],"a":"Forældre, der hjælper med musik, hjælper måske også med lektier","r":"Måske er det hjemmet, der giver både musikken og de gode karakterer. Så hjælper det ikke at tvinge alle til at spille violin. Pris og sværhedsgrad siger ikke noget om det."},
{"l":7575,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Prøv at ___ de to digte, og find ligheder.'","o":["sammelligne","samenligne","sammenline","sammenligne"],"a":"sammenligne","r":"Ordet består af 'sammen' og 'ligne', så det har dobbelt-m og gn."},
{"l":7600,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kendetegner nationalromantikken?","o":["Begejstring for folkets fortid, sprog og natur","Kritik af byernes fabrikker og arbejdsforhold","Interesse for storbyen og moderne teknologi","Tvivl på, at sproget kan beskrive noget som helst"],"a":"Begejstring for folkets fortid, sprog og natur","r":"Nationalromantikerne hyldede det nationale, f.eks. oldtiden, modersmålet og det danske landskab."},
{"l":7618,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder forleddet 'syn' i 'synkron' og 'syntese'?","o":["imod","sammen","efter","uden"],"a":"sammen","r":"Græsk 'syn' betyder sammen. Noget synkront sker samtidig, og en syntese samler flere dele til en helhed."},
{"l":7641,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'polyglot'?","o":["en person, der rejser til mange lande","en person, der samler på gamle sten","en person, der taler mange sprog","en person, der spiller flere instrumenter"],"a":"en person, der taler mange sprog","r":"'Poly' betyder mange, og 'glot' kommer af det græske ord for tunge. En polyglot behersker altså mange 'tunger', det vil sige sprog."},
{"l":7659,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Det var en ___ varm oktoberdag, så vi kunne bade.'","o":["usædvandlig","usedvanlig","usædvalig","usædvanlig"],"a":"usædvanlig","r":"Ordet skrives med æ og -vanlig, altså uden d efter n."},
{"l":7684,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken dansk forfatter skrev 'Lykke-Per' og fik Nobelprisen i litteratur i 1917?","o":["Henrik Pontoppidan","Georg Brandes","Holger Drachmann","J.P. Jacobsen"],"a":"Henrik Pontoppidan","r":"Pontoppidan delte Nobelprisen i 1917 med Karl Gjellerup. 'Lykke-Per' er hans mest kendte roman."},
{"l":7700,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvorfor nøjes? Du har fortjent det.' Hvad gør reklamen ved købet?","o":["Den viser, hvad køberen får for de sparede penge","Den får købet til at lyde som noget, du har fortjent","Den råder køberen til at nøjes med mindre","Den fortæller, hvorfor varen er bedre end andre"],"a":"Den får købet til at lyde som noget, du har fortjent","r":"Der står intet om varen, kun om dig. Du skal føle, at du har ret til at købe den."},
{"l":7718,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Vores klasse bør cykle med hjelm på udflugter. Undersøgelser viser, at hjelm mindsker risikoen for hovedskader.' Hvad er påstanden?","o":["Undersøgelser viser, at hjelme mindsker risikoen","Hovedskader er farlige for små børn","Vores klasse bør cykle med hjelm på udflugter","Børn cykler for hurtigt på vejene"],"a":"Vores klasse bør cykle med hjelm på udflugter","r":"Påstanden er det synspunkt, teksten vil have læseren til at acceptere. Undersøgelserne er belægget."},
{"l":7743,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'De to søskende vasker ___ op, så de får lige meget at lave.'","o":["skifteviis","skiftvis","skiftevist","skiftevis"],"a":"skiftevis","r":"Ordet består af 'skifte' og -vis, så e'et skal med, og der er ikke noget t til sidst."},
{"l":7762,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Hvis ___ person ringer, så tag imod en besked.'?","o":["nogen","nogle","noget","hvert"],"a":"nogen","r":"'Person' står i ental og er fælleskøn. Derfor skrives 'nogen', mens 'nogle' kun bruges foran flertal."},
{"l":7784,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"I hvilket sammensat ord er forleddet et verbum?","o":["bogreol","skrivebord","havebord","køkkenbord"],"a":"skrivebord","r":"Forleddet i 'skrivebord' kommer af verbet 'skrive'. I de andre ord er forleddet et navneord."},
{"l":7800,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg har aldrig været misundelig på min bror. Jeg har blot ført regnskab over, hvad han har fået hver jul siden 1998, og det er rent af interesse.' Skal læseren tro på fortælleren?","o":["Ja, for et så nøjagtigt regnskab kan man stole på","Ja, for fortælleren siger selv, at det er af interesse","Nej, for man fører ikke regnskab af ren interesse","Nej, for fortælleren har stjålet nogle af brorens gaver"],"a":"Nej, for man fører ikke regnskab af ren interesse","r":"Ingen fører regnskab over sin brors julegaver siden 1998 af ren interesse. Det, fortælleren gør, viser, at fortælleren er misundelig."},
{"l":7817,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kalder man fejlen i: 'Vi købte en ny skole taske.'?","o":["kongruensfejl","ordstillingsfejl","tegnsætningsfejl","særskrivning"],"a":"særskrivning","r":"Sammensatte ord skal skrives i ét ord på dansk. Det hedder en særskrivningsfejl, når de deles."},
{"l":7839,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Både Ali og Sara var ___ for præmien.'?","o":["glade","glad","gladt","gladen"],"a":"glade","r":"To personer forbundet med 'både … og' tæller som flertal, så tillægsordet skal stå i flertal."},
{"l":7858,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en klumme?","o":["En lang videnskabelig artikel fra et dansk universitet","En kort, personlig tekst fra en fast skribent i en avis","En neutral nyhed om dagens vejr og trafik","En oversigt over avisens mange læsere og abonnenter"],"a":"En kort, personlig tekst fra en fast skribent i en avis","r":"Klummen er kort og personlig og har ofte et humoristisk eller skævt blik på hverdagen."},
{"l":7882,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en 'moralistisk' person?","o":["opmuntrer andre til at holde ud","hjælper andre uden at tale om det","belærer andre om rigtigt og forkert","tager selv let på alle regler"],"a":"belærer andre om rigtigt og forkert","r":"Moralsk betyder, at man handler rigtigt. Moralistisk har en negativ klang og betyder, at man prædiker for andre om, hvad de skal gøre."},
{"l":7900,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Når en bog bliver filmatiseret, mister man noget, ingen taler om: Heltinden har ikke længere det ansigt, man selv gav hende. Hun har skuespillerens.' Hvad er det, skribenten beklager?","o":["At filmens skuespillere ofte er for gamle til rollen","At filmen ændrer på handlingen i romanens slutning","At forfatteren sjældent er med til at lave filmen","At man mister det billede, man selv havde af hende"],"a":"At man mister det billede, man selv havde af hende","r":"Når man læser, giver man selv heltinden et ansigt. Efter filmen har hun skuespillerens ansigt."},
{"l":7921,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolen har i tre år haft mobilfri frikvarterer. Ledelsen skriver, at ingen har klaget. Men da eleverne sidste år blev spurgt anonymt, svarede halvdelen, at de var utilfredse.' Hvad viser det anonyme svar?","o":["At man godt kan være utilfreds uden at klage","At ledelsen har løjet om, hvor mange der har klaget","At de fleste elever er glade for mobilfri frikvarterer","At mobilfri frikvarterer er blevet afskaffet igen"],"a":"At man godt kan være utilfreds uden at klage","r":"Ingen har klaget, men halvdelen svarer, at de er utilfredse, når de må være anonyme. Så man kan ikke regne med, at de, der tier, er glade."},
{"l":7942,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en gammel fortælling står 'huset i lys lue'. Hvad betyder 'lue'?","o":["aske","flamme","røg","sod"],"a":"flamme","r":"'Lue' er et ældre ord for flamme. Udtrykket 'stå i lys lue' bruges stadig om noget, der brænder kraftigt."},
{"l":7964,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken form er rigtig: 'Ordet otte staves med to ___.'?","o":["t:er","t,er","t'er","t.er"],"a":"t'er","r":"Når et enkelt bogstav bøjes, sætter man apostrof foran endelsen."},
{"l":7984,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'En øredøvende stilhed fyldte rummet.' Hvilket virkemiddel er der her?","o":["allitteration","lydord","gentagelse","oxymoron"],"a":"oxymoron","r":"To modsatte ord står lige op ad hinanden: Stilhed kan normalt ikke være øredøvende. Det kaldes et oxymoron."},
{"l":8003,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En film foregår i vikingetiden, men en kriger har armbåndsur på. Hvad kaldes sådan en fejl?","o":["en anakronisme","en allegori","en antitese","en analogi"],"a":"en anakronisme","r":"En anakronisme er noget, der er placeret i en forkert tid. I ordet gemmer sig det græske ord 'chronos', som betyder tid."},
{"l":8023,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Den syge hund måtte i ___ i to uger.'","o":["karrantæne","karantæne","karantene","karentæne"],"a":"karantæne","r":"Ordet har ét r og skrives med æ i næstsidste stavelse."},
{"l":8040,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'præmis' i en argumentation?","o":["en belønning, som vinderen af debatten får","en afsluttende bemærkning fra ordstyreren","en forudsætning, som en slutning bygger på","en indledende hilsen til alle tilhørerne"],"a":"en forudsætning, som en slutning bygger på","r":"Præmisserne er det, man går ud fra. Er præmissen forkert, holder konklusionen heller ikke. Forveksl den ikke med 'præmie', som er en belønning."},
{"l":8063,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Yusuf siger, at skolen bør give færre lektier. Sofie svarer: 'Så du vil altså afskaffe skolen!' Hvad har Sofie gjort?","o":["givet et belæg","brugt en eufemisme","gjort en indrømmelse","opstillet en stråmand"],"a":"opstillet en stråmand","r":"En stråmand er en forvrænget udgave af modstanderens synspunkt, som er nem at slå ned. Yusuf har jo ikke sagt det, Sofie tillægger ham."},
{"l":8085,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Romanen blev udgivet 'postumt'. Hvad betyder det?","o":["efter forfatterens død","uden forfatterens navn","før forfatterens debut","i forfatterens fødeby"],"a":"efter forfatterens død","r":"Noget postumt sker efter en persons død. Ordet bruges især om værker og hædersbevisninger."},
{"l":8103,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvem udfører handlingen i: 'Broen blev tegnet af en ung arkitekt.'?","o":["broen","en ung arkitekt","sætningens grundled","sætningens verballed"],"a":"en ung arkitekt","r":"I passiv står den, der handler, efter 'af'. Grundleddet 'broen' er det, der sker noget med."},
{"l":8123,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør et land, når det 'annekterer' et område?","o":["det sælger området til et naboland","det opgiver området efter en aftale","det indlemmer området i sit eget land","det kortlægger området med satellitter"],"a":"det indlemmer området i sit eget land","r":"At annektere er at lægge et område ind under sit eget land, som regel uden at have ret til det. Ordet ses tit i historiebøger."},
{"l":8145,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forskerne fandt en 'kausal' sammenhæng mellem to fænomener. Hvad betyder det?","o":["de to er helt tilfældigt ens","de to forekommer kun sjældent","det ene er ældre end det andet","det ene er årsag til det andet"],"a":"det ene er årsag til det andet","r":"'Kausal' kommer af latin 'causa', som betyder årsag. Det er stærkere end korrelation, hvor to ting bare følges ad."},
{"l":8169,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kaldes de følelser og bibetydninger, et ord kan vække?","o":["konnotation","denotation","kongruens","modus"],"a":"konnotation","r":"Ordet 'hjem' betyder et sted, men det vækker også tryghed. Den ekstra betydning er ordets konnotation."},
{"l":8190,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at to computerprogrammer er 'kompatible'?","o":["de koster det samme","de kan fungere sammen","de er lavet af samme firma","de fylder lige meget"],"a":"de kan fungere sammen","r":"Kompatibel betyder forenelig. To dele, der er kompatible, kan bruges sammen uden problemer."},
{"l":8206,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilke ord skal have stort: 'Min tante arbejder som frivillig for røde kors i Kolding.'?","o":["kun røde","kun kors","røde og kors","kun frivillig"],"a":"røde og kors","r":"Røde Kors er navnet på en organisation, og navnets to ord får begge stort."},
{"l":8228,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Det er vinter i 1864. En ung bondekone går langs landevejen og fryser.' Hvad gør det ved læseren, at fortiden her er fortalt i nutid?","o":["Det føles, som om det hele er opdigtet","Det føles, som om det er meget længe siden","Det føles, som om det sker i fremtiden","Det føles, som om det sker lige nu"],"a":"Det føles, som om det sker lige nu","r":"Når noget fra fortiden fortælles i nutid, rykker det tæt på. Det virker, som om vi selv står på landevejen."},
{"l":8250,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken af forkortelserne skrives uden punktum efter?","o":["FN","nr","stk","ca"],"a":"FN","r":"Initialforkortelser af navne skrives med store bogstaver og uden punktum. De andre skal have punktum."},
{"l":8272,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilke to ord skal der stå komma: 'Jeg ville gerne købe billet men da vi kom var der udsolgt.'?","o":["købe og da","billet og kom","men og var","gerne og vi"],"a":"billet og kom","r":"Der skal komma foran 'men' mellem de to sætninger og efter ledsætningen 'da vi kom'."},
{"l":8294,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning indeholder en kommafejl?","o":["Filmen, vi så i aftes, var god.","Da den var slut, gik vi hjem.","Efter filmen, gik vi hjem og spiste.","Jeg tror, at den vinder en pris."],"a":"Efter filmen, gik vi hjem og spiste.","r":"'Efter filmen' er et forholdsled uden udsagnsled, og sådan et led skal ikke have komma efter sig."},
{"l":8317,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Det kræver meget arbejde at ___ et gammelt hus.'","o":["vedlige holde","vedligholde","vedligeholle","vedligeholde"],"a":"vedligeholde","r":"Ordet skrives i ét og består af 'ved', 'lige' og 'holde'."},
{"l":8338,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Anna købte Wienerbrød i Wien på vej til Alperne.'?","o":["Wienerbrød","Anna","Wien","Alperne"],"a":"Wienerbrød","r":"Wienerbrød er et almindeligt navneord og skrives med lille, selvom første led stammer fra bynavnet Wien."},
{"l":8360,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad er forskellen på tankestreg og bindestreg?","o":["Bindestregen er længere og står med mellemrum","Tankestregen er længere og står med mellemrum","Tankestregen står kun i tal og aldrig i tekst","Bindestregen står kun sidst i en hel sætning"],"a":"Tankestregen er længere og står med mellemrum","r":"Tankestregen er den lange streg, som markerer en pause. Bindestregen er kort og binder ord sammen."},
{"l":8382,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Hvad der skete med nøglen da vi var væk aner jeg ikke.'?","o":["skete","aner","væk","ikke"],"a":"væk","r":"Alt før 'aner' er ledsætning, så slutkommaet skal stå efter 'væk'."},
{"l":8402,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken forfatter opfandt Janteloven i en roman fra 1933?","o":["Tom Kristensen","Hans Scherfig","Tove Ditlevsen","Aksel Sandemose"],"a":"Aksel Sandemose","r":"Janteloven stammer fra Aksel Sandemoses roman 'En flygtning krydser sit spor'. Den beskriver et småligt miljø."},
{"l":8426,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'I november faldt den første sne på den nordlige halvkugle og i nordeuropa.'?","o":["nordeuropa","nordlige","halvkugle","november"],"a":"nordeuropa","r":"Nordeuropa er et geografisk navn. 'Nordlige' er et almindeligt tillægsord."},
{"l":8445,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad sker der, når en uretfærdigt anklaget person bliver 'rehabiliteret'?","o":["personen bliver flyttet til en anden by","personens gode navn bliver genoprettet","personen får lov at klage en gang til","personen bliver tvunget til at forlade landet"],"a":"personens gode navn bliver genoprettet","r":"Rehabilitere betyder her at give en person sin ære og sit gode navn tilbage. Ordet bruges også om genoptræning efter sygdom."},
{"l":8468,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'bevare status quo'?","o":["at kæmpe for at få en højere stilling","at opbevare noget meget værdifuldt","at lade tingene forblive, som de er","at holde sin plan hemmelig"],"a":"at lade tingene forblive, som de er","r":"'Status quo' er latin for 'den tilstand, der er nu'. Ordet bruges meget i avisers omtale af sager, hvor intet ændres."},
{"l":8488,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er forskellen på de to 'hvis' i: 'Hvis du vil, kan vi besøge pigen, hvis far er pilot.'?","o":["Det første er et stedord, det andet et bindeord.","Begge to er bindeord, der angiver en betingelse.","Begge to er stedord, der viser, hvem noget tilhører.","Det første er et bindeord, det andet et stedord."],"a":"Det første er et bindeord, det andet et stedord.","r":"Det første 'hvis' angiver en betingelse. Det andet er et henførende stedord, der viser, at faren hører til pigen."},
{"l":8513,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en bevægelse er 'i sin vorden'?","o":["at den stadig er under udvikling","at den er på sit højeste","at den snart går i opløsning","at den er forbudt ved lov"],"a":"at den stadig er under udvikling","r":"'Vorden' kommer af det gamle verbum 'vorde', som betyder at blive. Noget, der er i sin vorden, er altså i færd med at blive til."},
{"l":8528,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Hold da op, mand, det var altså sindssygt vildt!' Hvordan vil du beskrive sproget?","o":["Højtideligt og gammeldags","Uformelt og talesprogsnært","Fagligt og upersonligt","Poetisk og rimet"],"a":"Uformelt og talesprogsnært","r":"Udbrud og ord som 'altså' og 'mand' hører talesproget til. Sproget er uformelt og kommer tæt på en samtale."},
{"l":8554,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad er fejlen i skriftsprog i: 'Jeg har ikke set ingen i dag.'?","o":["særskrivning","kongruensfejl","dobbelt nægtelse","forkert tid"],"a":"dobbelt nægtelse","r":"'Ikke' og 'ingen' nægter begge to. På standarddansk skal der kun være ét nægtende ord: 'Jeg har ikke set nogen i dag.'"},
{"l":8575,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led står i forfeltet i sætningen: 'I weekenden besøgte Sara sin farmor i Kolding.'","o":["Sara","sin farmor","i Kolding","I weekenden"],"a":"I weekenden","r":"Forfeltet er pladsen foran det bøjede udsagnsord, her 'besøgte'. Kun 'I weekenden' står foran det, så grundleddet 'Sara' må stå bagefter."},
{"l":8605,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En undersøgelse er 'empirisk'. Hvad bygger den på?","o":["observationer og indsamlede data","forskerens helt personlige tro på noget","gamle myter og sagn","rene tankeeksperimenter"],"a":"observationer og indsamlede data","r":"Empiri er det, man faktisk har iagttaget eller målt. En empirisk undersøgelse hviler derfor på erfaring og ikke kun på tanker."},
{"l":8629,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken novellesamling udgav Villy Sørensen i 1953?","o":["Himmerlandshistorier","Sære historier","Vintereventyr","Den onde lykke"],"a":"Sære historier","r":"Med 'Sære historier' fornyede Villy Sørensen den danske novelle med fantastiske og gådefulde fortællinger."},
{"l":8651,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kendetegner konkretisme i poesi?","o":["At digtet fortæller en lang og spændende historie","At digtet bygger på folkets gamle viser og sagn","At ordets form, lyd og placering selv er det vigtige","At digtet skal kritisere konkrete politiske forhold"],"a":"At ordets form, lyd og placering selv er det vigtige","r":"I konkretismen er sproget selv materialet. Ordene ses og høres som ting, mere end de fortæller om noget."},
{"l":8671,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Påstand A: Alle elever på skolen læser mere end to timer om ugen. Påstand B: De fleste elever på skolen læser mere end en time om ugen.' Hvorfor er påstand A lettest at afkræfte?","o":["A handler om flere timer end B, og det gør den svagere","A bruger et mere præcist tal end B gør","B handler om elever, og det gør A ikke","Det er nok at finde én elev, der læser mindre"],"a":"Det er nok at finde én elev, der læser mindre","r":"En påstand med 'alle' falder, hvis blot én elev læser mindre. 'De fleste' tåler mange undtagelser."},
{"l":8695,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Et gammelt brev 'kompromitterede' borgmesteren. Hvad gjorde brevet?","o":["bragte hende i et dårligt lys","hjalp hende til en god aftale","gav hende stor ros i pressen","fik hende til at flytte væk"],"a":"bragte hende i et dårligt lys","r":"At kompromittere nogen er at skade deres gode navn. Ordet betyder noget andet end at indgå et kompromis."},
{"l":8710,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læreren forklarer hjertet ved at sammenligne det med en pumpe. Hvad kaldes sådan en sammenligning, der bygger på ligheder i funktion?","o":["anagram","analogi","antitese","autonomi"],"a":"analogi","r":"En analogi forklarer noget ukendt ved hjælp af noget kendt, der fungerer på samme måde. Et anagram er derimod et ord, hvor bogstaverne er flyttet rundt."},
{"l":8732,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad laver en 'kurator' på et kunstmuseum?","o":["reparerer gamle og beskadigede malerier i kælderen","sælger billetter og passer garderoben","udvælger værker og tilrettelægger udstillinger","fører regnskabet for museets butik"],"a":"udvælger værker og tilrettelægger udstillinger","r":"Latin 'curare' betyder at drage omsorg for. Kuratoren bestemmer, hvad der skal vises, og hvordan det hænger sammen."},
{"l":8755,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord beskriver bedst en stille, dyb tristhed uden en bestemt årsag?","o":["eufori","ekstase","panik","melankoli"],"a":"melankoli","r":"Melankoli er en tungsindig sindsstemning. De græske ord bag betyder 'sort galde', som man engang troede var årsagen."},
{"l":8775,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Radiostationen sender på en bestemt ___.'","o":["frekvens","frekvents","frækvens","frekvenz"],"a":"frekvens","r":"Ordet skrives med kv og ender på -ens uden t."},
{"l":8794,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er magisk realisme?","o":["Tryllekunstnere fortæller om deres arbejde","Overnaturlige hændelser beskrives som naturlige","Fakta fremlægges nøgternt og uden billedsprog","Eventyr fra fortiden gengives ord for ord"],"a":"Overnaturlige hændelser beskrives som naturlige","r":"I magisk realisme blandes det virkelige og det overnaturlige, uden at nogen i teksten undrer sig."},
{"l":8816,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Kære læser, jeg ved ikke, hvordan denne historie skal ende. Måske skulle jeg lade hovedpersonen falde i søvn.' Hvad kaldes det, når en tekst sådan taler om sig selv som tekst?","o":["naturalisme","reportage","metafiktion","allegori"],"a":"metafiktion","r":"Metafiktion afslører, at teksten er digtet. Her gør fortælleren opmærksom på sit eget arbejde med historien."},
{"l":8838,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad gør man, når man perspektiverer en tekst?","o":["Man skriver et kort referat af handlingen i teksten","Man finder alle tekstens sproglige billeder og tæller dem","Man undersøger, hvor mange personer der er med i teksten","Man sætter teksten i forhold til andre tekster eller tiden"],"a":"Man sætter teksten i forhold til andre tekster eller tiden","r":"Når man perspektiverer, ser man teksten i et større lys, f.eks. andre værker, perioden eller samfundet."},
{"l":8860,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvorfor står hjemlen sjældent direkte i et argument?","o":["Fordi den ofte er en antagelse, som man regner med deles","Fordi den er forbudt i skriftlige debatindlæg","Fordi den altid står som overskrift på teksten","Fordi den kun findes i digte og ikke i prosatekster"],"a":"Fordi den ofte er en antagelse, som man regner med deles","r":"Hjemlen er tit noget, afsenderen går ud fra, at modtageren er enig i. Derfor kan det være nyttigt at trække den frem og teste den."},
{"l":8880,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad skal der stå? 'Den elev, som ___ at tage et efterskoleår, kan tale med vejlederen.'","o":["overveje","overvejer","overvejrer","overvejerer"],"a":"overvejer","r":"Udsagnsordet står i nutid i ledsætningen, så det får -r."},
{"l":8897,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad sætter en 'hedonist' højest i livet?","o":["pligt og orden","viden og fornuft","nydelse og velvære","ære og berømmelse"],"a":"nydelse og velvære","r":"Det græske 'hedone' betyder nydelse. En hedonist mener, at det gode liv er det behagelige liv."},
{"l":8918,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Kun én af sætningerne er rigtig uden komma. Hvilken?","o":["At han spiller skak kræver tålmodighed af ham.","Hvis man spiller skak kræver det tålmodighed.","Den der spiller skak må have tålmodighed.","At spille skak kræver tålmodighed og overblik."],"a":"At spille skak kræver tålmodighed og overblik.","r":"'At spille skak' er navneform og ikke en ledsætning. De tre andre rummer en ledsætning, der skal afsluttes med komma."},
{"l":8938,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad er hovedfunktionen i skiltet: 'Husk at lukke lågen efter dig.'","o":["den appellative","den ekspressive","den poetiske","den fatiske"],"a":"den appellative","r":"Den appellative funktion prøver at få modtageren til at gøre noget. Skiltet opfordrer læseren til at lukke lågen."},
{"l":8957,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Overskrift: Chokolade gør dig klogere. I artiklen står der, at lande med et højt forbrug af chokolade også har flest prismodtagere inden for forskning.' Hvad er særligt problematisk ved overskriftens konklusion?","o":["Tallene siger ikke, hvilken slags chokolade forskerne spiser","Tallene handler om lande, men overskriften handler om dig","Tallene kan ikke regnes om til procenter","Tallene handler kun om de fattigste lande"],"a":"Tallene handler om lande, men overskriften handler om dig","r":"Tallene gælder lande, ikke personer. Rige lande kan have både chokolade og forskning, og det siger intet om, hvad der gør dig klogere."},
{"l":8980,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Svirrefluen ligner en hveps, så fugle lader den være. Hvad kaldes det fænomen?","o":["parasitisme","fotosyntese","mimikry","migration"],"a":"mimikry","r":"Mimikry er, når et harmløst dyr efterligner et farligt. Ordet hænger sammen med 'mimik'."},
{"l":9000,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Sæt ind: 'Det er et ___ spørgsmål til emnet.'","o":["relevent","rellevant","revelant","relevant"],"a":"relevant","r":"Ordet ender på -ant. Mange bytter om på l og v, men rækkefølgen er re-le-vant."},
{"l":9017,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner 'stagflation' i økonomien?","o":["stilstand og stigende priser på samme tid","høj vækst og faldende priser på samme tid","stærk valuta og lav arbejdsløshed","mange nye firmaer og lave renter"],"a":"stilstand og stigende priser på samme tid","r":"Ordet er sat sammen af 'stagnation' og 'inflation'. Det er en særlig vanskelig situation for et land."},
{"l":9040,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det glæder os, at Søndergade endelig får den nedsatte fart, som beboerne har kæmpet for. Skiltene sættes op i næste uge.' Hvad afslører ordene 'det glæder os' og 'endelig'?","o":["At afsenderen er imod den lavere hastighed","At afsenderen ikke er neutral i sagen","At skiltene er blevet sat op for længe siden","At beboerne ikke har bedt om nedsat fart"],"a":"At afsenderen ikke er neutral i sagen","r":"En nyhed kunne bare fortælle, at skiltene kommer. Ordene viser, hvem afsenderen holder med."},
{"l":9060,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find ordet: 'Forfatteren sendte sit ___ til forlaget.'","o":["manusskript","manuscript","manuskript","manuskribt"],"a":"manuskript","r":"Ordet består af latinske dele for 'hånd' og 'skrevet'. På dansk skrives det med k og ét s."},
{"l":9080,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Regn. Mørke. Ingen biler på vejen.' Hvad kaldes det, når sætninger er forkortet ved at udelade led?","o":["kiasme","oxymoron","hyperbel","ellipse"],"a":"ellipse","r":"I en ellipse er noget udeladt, men læseren forstår det alligevel. Her giver det en knap og nøgen stemning."},
{"l":9100,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvordan deler man 'lærerværelse' rigtigt ved linjeskift?","o":["lærer-værelse","lære-rværelse","lærerv-ærelse","lærervære-lse"],"a":"lærer-værelse","r":"Et sammensat ord deles helst der, hvor de to ord mødes, altså mellem 'lærer' og 'værelse'."},
{"l":9120,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'I ___ lærer man at tale overbevisende.'","o":["rhetorik","retorik","rettorik","retorrik"],"a":"retorik","r":"Ordet har ét t og ét r i midten, og på dansk er der intet h efter r'et."},
{"l":9145,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Morfar 'rider sin kæphest' ved middagsbordet. Hvad gør han?","o":["skynder sig at gå fra bordet","fortæller om livet på landet i gamle dage","vender tilbage til sit yndlingsemne","driller alle dem ved bordet"],"a":"vender tilbage til sit yndlingsemne","r":"En kæphest er et emne, som en person altid vender tilbage til. Andre kan godt synes, at det bliver lidt for meget."},
{"l":9160,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord beskriver en fremstilling, der er lang og fuld af unødige detaljer?","o":["kortfattet","fyndig","præcis","vidtløftig"],"a":"vidtløftig","r":"Vidtløftig betyder omstændelig og langtrukken. Det er det modsatte af fyndig, altså kort og slagkraftig."},
{"l":9180,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Vi stod på en kold ___ og ventede på toget.'","o":["perron","peron","perrong","pærron"],"a":"perron","r":"Ordet kommer fra fransk og har dobbelt-r og et n til sidst uden g."},
{"l":9202,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Morfemet '-fobi' findes i fremmedord som 'klaustrofobi'. Hvad betyder det?","o":["lære","frygt","skrift","styre"],"a":"frygt","r":"'-fobi' kommer af et græsk ord for frygt. Klaustrofobi er frygt for lukkede rum."},
{"l":9223,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken stemning forbindes oftest med Blichers skildringer af heden?","o":["Hygge og tryghed","Håb og forventning","Vemod og ensomhed","Stolthed og glæde"],"a":"Vemod og ensomhed","r":"Hedens øde landskab giver Blichers tekster en vemodig tone. Naturen spejler personernes skæbner."},
{"l":9242,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord fuldender sætningen: 'Det var ___ af ham at påstå noget om vulkaner, for han vidste intet om emnet.'","o":["elegant","galant","tolerant","ignorant"],"a":"ignorant","r":"Ignorant betyder uvidende og kommer af latin 'ignorare'. Ordet bruges netop, når nogen mangler viden."},
{"l":9257,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvordan opfører en person sig, der er 'vægelsindet'?","o":["skifter mening igen og igen","tåler ikke at blive modsagt","bliver let vred på andre","husker næsten aldrig noget"],"a":"skifter mening igen og igen","r":"Sindet vakler frem og tilbage. En vægelsindet person kan ikke holde fast i en beslutning."},
{"l":9282,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om teksten på skiltet?","o":["Der stod: »Ingen adgang på skiltet«.","Der stod »Ingen adgang« på skiltet.","Der stod »Ingen« adgang på skiltet.","»Der stod Ingen adgang« på skiltet."],"a":"Der stod »Ingen adgang« på skiltet.","r":"Anførselstegnene omslutter præcis de ord, der står på skiltet."},
{"l":9302,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en forfatter er 'obskur'?","o":["at forfatteren har stor indflydelse","at forfatteren skriver under falsk navn","at kun få kender til forfatteren","at forfatteren kun udgiver digte"],"a":"at kun få kender til forfatteren","r":"Latin 'obscurus' betyder mørk. En obskur forfatter står i mørket, altså uden for offentlighedens lys."},
{"l":9325,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er grundtanken i 'nihilisme'?","o":["at alle mennesker fra fødslen er nøjagtig lige meget værd","at al viden kommer fra sansernes erfaring","at naturen altid bør beskyttes mod mennesket","at der ikke findes faste værdier eller dybere mening"],"a":"at der ikke findes faste værdier eller dybere mening","r":"Latin 'nihil' betyder intet. Nihilismen benægter, at der findes faste værdier eller en dybere mening."},
{"l":9345,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Et samfund helt uden problemer er en ___, som næppe kan blive virkelighed.'","o":["utopi","utopie","ytopi","uttopi"],"a":"utopi","r":"Ordet kommer fra græsk, har ét t og ender på -i."},
{"l":9366,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvem holdt i 1802 forelæsninger i København, der bragte romantikkens ideer til Danmark?","o":["Georg Brandes","Henrik Steffens","N.F.S. Grundtvig","Ludvig Holberg"],"a":"Henrik Steffens","r":"Henrik Steffens' forelæsninger inspirerede Adam Oehlenschläger, der kort efter skrev 'Guldhornene'."},
{"l":9386,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilke ord skal have stort: 'Vi så ballet på det kongelige teater.'?","o":["kun kongelige og teater","kun teater","det, kongelige og teater","kun det og teater"],"a":"det, kongelige og teater","r":"Navnet er Det Kongelige Teater, og hele navnet får stort."},
{"l":9407,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er det faglige ord for lydord som 'pling', 'klask' og 'vov'?","o":["akronym","eufemisme","alliteration","onomatopoietikon"],"a":"onomatopoietikon","r":"Ordet betyder 'navnedannelse' på græsk. Lydord efterligner den lyd, de betegner."},
{"l":9433,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvor mange morfemer har ordet 'drengenes'?","o":["fire","tre","to","fem"],"a":"fire","r":"Roden 'dreng' får flertal '-e', bestemt form '-ne' og ejefald '-s'. Hver del bærer sin egen betydning, så der er fire morfemer."},
{"l":9452,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder tillægsordet i udtrykket 'en prosaisk hverdag'?","o":["digterisk og drømmende","nøgtern og uden poesi","farlig og spændende","højtidelig og festlig"],"a":"nøgtern og uden poesi","r":"Prosa er ubunden tale i modsætning til digte. I overført betydning er det prosaiske det jævne og fantasiløse."},
{"l":9469,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Jeg ringede ikke, fordi jeg var sur.' Hvilke to meninger kan sætningen have?","o":["Jeg ringede sent på dagen, eller også ringede jeg til en anden","Jeg er sur nu, eller også var jeg sur, længe før jeg ringede til nogen","Vreden fik mig til at lade være, eller også ringede jeg af en anden grund","Vreden er forbi, eller også er det den anden, der er blevet sur på mig"],"a":"Vreden fik mig til at lade være, eller også ringede jeg af en anden grund","r":"'Ikke' kan knytte sig til 'ringede' eller til grunden. Enten blev opkaldet aldrig foretaget, eller også skete det, men ikke af vrede."},
{"l":9490,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'xenofob' bange for?","o":["det gamle","det mørke","det høje","det fremmede"],"a":"det fremmede","r":"Xeno- er græsk for fremmed, og -fobi betyder frygt. Frygt for mørke hedder noget andet."},
{"l":9510,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken omskrivning med navneform har samme mening som: 'Villads håbede, at han ville vinde.'","o":["Villads håbede at vinde.","Villads ville håbe at vinde.","Villads vandt at håbe.","Villads håbede at blive vundet."],"a":"Villads håbede at vinde.","r":"Når grundleddet er det samme i begge dele, kan at-sætningen skrives om til 'at' og navneform. Betydningen er den samme, men sætningen bliver kortere."},
{"l":9532,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Forskere undersøger, hvordan sproget varierer efter social baggrund og ikke efter landsdel. Hvad kaldes en sådan sprogvariant?","o":["dialekt","sociolekt","idiolekt","rigsdansk"],"a":"sociolekt","r":"En sociolekt hænger sammen med en social gruppe, en dialekt med et geografisk område. En idiolekt er den enkelte persons eget sprog."},
{"l":9554,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken form står tillægsordet i efter ejefald: 'Emmas ___ hus ligger ved stranden.'","o":["gammelt","gammel","gamle","gamles"],"a":"gamle","r":"Efter et ejefald står tillægsordet i bestemt form, ligesom efter 'det'. Derfor hedder det 'Emmas gamle hus', selvom 'hus' er intetkøn."},
{"l":9575,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læseren opdager først i novellens sidste sætning, at fortælleren er familiens hund. Hvad gør den slutning ved læseren?","o":["Man holder op med at tro på historien","Man forstår, at novellen er en fabel med en moral","Man ved nu, hvordan historien vil fortsætte","Man må tænke hele historien igennem på ny"],"a":"Man må tænke hele historien igennem på ny","r":"Når man pludselig ved, hvem der fortæller, ser alt det, man har læst, anderledes ud. Så får man lyst til at gå tilbage og se, hvad der pegede på det."},
{"l":9595,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Træneren siger, at tillid er et 'sine qua non' for godt holdspil. Hvad mener hun?","o":["Uden tillid går det slet ikke","Tillid kan man sagtens undvære","Tillid kommer først til sidst","Tillid er kun for de ældste"],"a":"Uden tillid går det slet ikke","r":"Latin 'sine qua non' betyder 'uden hvilken ikke'. Det er altså en betingelse, som man ikke kan komme uden om."},
{"l":9615,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Fortæl begivenhederne i ___ rækkefølge, altså i den orden, de skete.'","o":["cronologisk","kronologisk","kronnologisk","kronoligisk"],"a":"kronologisk","r":"Ordet kommer fra græsk 'khronos', der betyder tid. På dansk skrives det med k og ét n."},
{"l":9635,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'En politiker bliver citeret for: Jeg har aldrig sagt, at skolen skal lukke. Af hele interviewet fremgår det, at hun sagde: Jeg har aldrig sagt, at skolen skal lukke i år.' Hvad ændrer udeladelsen?","o":["Det lyder, som om skolen lukker i år","Det lyder, som om lukningen er blevet udskudt","Det lyder, som om hun aldrig vil lukke skolen","Det lyder mere præcist, end hun egentlig sagde det"],"a":"Det lyder, som om hun aldrig vil lukke skolen","r":"To små ord ændrer det hele: 'I år' åbnede for en lukning senere. Uden dem lyder det, som om den er helt udelukket."},
{"l":9655,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvem er 'enfant terrible' i et kunstmiljø?","o":["den, der er yngst og mest generet","den, der betaler for de andres arbejde","den, der holder orden i foreningen","den, der provokerer og bryder normerne"],"a":"den, der provokerer og bryder normerne","r":"Fransk for 'det frygtelige barn'. Udtrykket bruges om en person, der vækker opsigt ved at trodse sit miljø."},
{"l":9675,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Hans hjælp har været ___ for projektet.'","o":["uundværlig","uunværlig","uundverlig","uudværlig"],"a":"uundværlig","r":"Ordet består af 'u' og 'undværlig', så der er to u'er efter hinanden, og d'et skal med."},
{"l":9697,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad er forskellen på 'barnlig' og 'barnagtig', når man beskriver en voksen?","o":["'barnlig' er det mest negative ord","'barnagtig' er det mest negative ord","de to ord er altid synonymer","'barnagtig' handler om alder"],"a":"'barnagtig' er det mest negative ord","r":"Endelsen '-agtig' giver her en negativ klang: en barnagtig voksen opfører sig umodent. 'Barnlig' kan også være positivt, f.eks. 'barnlig glæde'."},
{"l":9719,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken deling af 'uheldigvis' viser ordets morfemer?","o":["uh + eld + ig + vis","u + hel + dig + vis","u + held + ig + vis","uheld + i + gvis"],"a":"u + held + ig + vis","r":"Roden er 'held'. Forstavelsen 'u-' vender betydningen, '-ig' danner et tillægsord, og '-vis' danner et biord."},
{"l":9740,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Fru Berg var overbevist om, at hun var byens mest beskedne menneske, og det fortalte hun gerne alle om.' Hvad gør sætningen morsom?","o":["At hun bor i en lille by og kender alle","At hun er meget stille og aldrig siger noget","At hun i virkeligheden er meget beskeden","At hun praler af, hvor beskeden hun er"],"a":"At hun praler af, hvor beskeden hun er","r":"Den, der fortæller alle om sin beskedenhed, er netop ikke beskeden. Teksten karakteriserer hende indirekte med ironi."},
{"l":9760,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I en gammel roman kaldes en bonde 'vindskibelig'. Hvad siger det om ham?","o":["at han var flittig og stræbsom","at han var rig og stolt af sin gård","at han kunne bygge møller og skibe","at han ofte skiftede sin mening"],"a":"at han var flittig og stræbsom","r":"Vindskibelighed er et gammelt ord for flid og driftighed. Det har intet med vind eller skibe at gøre."},
{"l":9780,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Den nye bog er et godt ___ til lærebogen, fordi den dækker det, der mangler.'","o":["kompliment","komplement","kompelment","komplemænt"],"a":"komplement","r":"Med e betyder ordet en tilføjelse, der gør noget helt. 'Kompliment' med i betyder ros."},
{"l":9802,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Den Holbergske komedie blev spillet på Det Kongelige Teater i København.'?","o":["Kongelige","Teater","Holbergske","København"],"a":"Holbergske","r":"Tillægsord dannet af personnavne skrives med lille: holbergsk."},
{"l":9825,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Et ___ er en påstand, der virker selvmodsigende, men alligevel kan være sand.'","o":["parradoks","paradogs","parodoks","paradoks"],"a":"paradoks","r":"Ordet kommer fra græsk, har ét r og ender på -ks."},
{"l":9840,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Da rygtet spredte sig, opstod der ___ blandt fansene.'","o":["hysteri","histeri","hystæri","hysterie"],"a":"hysteri","r":"Ordet kommer fra græsk, skrives med y og ender på -i."},
{"l":9865,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'sofisme'?","o":["en klog og fuldstændig indlysende grundsætning","en slutning, der ser gyldig ud, men er fejlagtig","en mild omskrivning af noget ubehageligt","en samtale om, hvad visdom egentlig er"],"a":"en slutning, der ser gyldig ud, men er fejlagtig","r":"Sofisterne var græske lærere, som Platon anklagede for at bruge smarte argumenter frem for sandhed."},
{"l":9885,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Der findes ingen sandheder, der gælder for alle, skrev Mikael i sin stil. Læreren satte et spørgsmålstegn i margenen og skrev: Gælder det også for alle?' Hvad er lærerens kritik?","o":["At Mikael har glemt at give stilen en overskrift","At Mikael bør bruge flere eksempler i sin stil","At Mikaels sætning modsiger sig selv","At Mikael har stavet flere ord forkert"],"a":"At Mikaels sætning modsiger sig selv","r":"Mikael skriver, at ingen sandhed gælder for alle. Men det skal jo selv gælde for alle, og så modsiger han sig selv. Det er det, læreren spørger til."},
{"l":9906,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord er komma et krav: 'Læreren der havde sagt at prøven ville blive let hvis vi øvede os fik ret.'?","o":["øvede","fik","ret","os"],"a":"os","r":"Den lange indskudte ledsætning med de to andre inde i sig slutter efter 'os'. Så følger udsagnsleddet 'fik'."},
{"l":9927,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Alle elever bør læse Karen Blixen, fordi hun er en berømt forfatter.' Hvilken hjemmel bygger argumentet på?","o":["At elever bør læse det, der er berømt","At Karen Blixen har skrevet mange bøger","At alle elever kan lide at læse historier","At forfattere bliver berømte af at skrive godt"],"a":"At elever bør læse det, der er berømt","r":"Hjemlen er antagelsen mellem belæg og påstand. Den er diskutabel, for berømmelse er ikke nødvendigvis et godt kriterium."},
{"l":9945,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'I en ulveflok er der et tydeligt ___.'","o":["hieraki","hierarki","hirarki","hierarchi"],"a":"hierarki","r":"Ordet kommer fra græsk og skrives med ie og -arki, ligesom 'monarki'."},
{"l":9968,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Problemet med at gøre noget for sidste gang er, at man sjældent ved det. En dag løftede min far mig op, satte mig ned igen og løftede mig aldrig mere. Ingen af os lagde mærke til det.' Hvad er det alvorlige i uddraget?","o":["At fædre ikke kan løfte deres børn, når de bliver tunge og store","At fortælleren er vred på sin far over en hændelse","At noget kan være slut, uden at nogen opdager det","At man bør skrive alle sine oplevelser ned i en dagbog"],"a":"At noget kan være slut, uden at nogen opdager det","r":"En dag blev fortælleren løftet for sidste gang, og ingen af dem vidste det. Sådan kan noget, der betyder meget, stoppe, uden at nogen lægger mærke til det."},
{"l":9985,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes to modsatte påstande, der begge virker lige velbegrundede?","o":["autonomi","agronomi","astronomi","antinomi"],"a":"antinomi","r":"Anti- betyder mod, og -nomi betyder lov. Filosoffen Immanuel Kant brugte ordet om to modsatte påstande, der begge kan begrundes."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
